-- =====================================================================
--  BLOC E - VERIFICATION
--  Attendu : 2 grilles, 6 sujets, 30 etalons, 2 gabarits,
--  et AUCUN sujet a moins de 3 etalons.
-- =====================================================================

select 'grilles' as objet, count(*) as n from public.rubrics where matiere = 'hggsp'
union all select 'sujets', count(*) from public.subject_cards where matiere = 'hggsp'
union all select 'etalons', count(*) from public.benchmark_cards b
  join public.subject_cards s on s.id = b.subject_id where s.matiere = 'hggsp'
union all select 'gabarits', count(*) from public.dossier_templates where matiere = 'hggsp';

select s.id, s.exercise_type, s.status, count(b.id) as etalons
from public.subject_cards s
left join public.benchmark_cards b on b.subject_id = s.id
where s.matiere = 'hggsp'
group by s.id, s.exercise_type, s.status
order by s.id;
